package main

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

func TestClipPythonVectors(t *testing.T) {
	// Generated by the actual Python contract function, without importing runtime dependencies.
	raw, err := os.ReadFile("testdata/clip_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Text  string `json:"text"`
		Limit int    `json:"limit"`
		Want  string `json:"want"`
	}
	if err = json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	for i, tc := range cases {
		if got := clipAppendContent(tc.Text, tc.Limit); got != tc.Want {
			t.Errorf("case %d: got %q want %q", i, got, tc.Want)
		}
	}
}
func TestEventMappingAndJournal(t *testing.T) {
	cases := []struct {
		wire, kind string
		fields     map[string]any
		check      string
		want       any
	}{
		{"session.input_transcript.delta", "transcript", map[string]any{"delta": "hello", "start_ms": 5.9, "end_ms": true}, "speaker", "caller"},
		{"session.output_transcript.delta", "transcript", map[string]any{"delta": "hi"}, "speaker", "assistant"},
		{"session.delegation.created", "delegation", map[string]any{"delegation": map[string]any{"id": "d"}, "offset_ms": 4.0}, "target", "client"},
		{"session.delegation.created", "other", map[string]any{"delegation": map[string]any{}}, "wire_type", "session.delegation.created"},
		{"session.instructions.appended", "append_ack", map[string]any{"client_event_id": "c"}, "kind", "instructions"},
		{"session.thinking.appended", "append_ack", nil, "kind", "thinking"}, {"session.commentary.appended", "append_ack", nil, "kind", "commentary"},
		{"error", "error", map[string]any{"error": map[string]any{"code": "bad", "message": "bad message", "type": "invalid", "client_event_id": "c"}}, "error_type", "invalid"},
		{"transport.dtmf.received", "dtmf", map[string]any{"event": "5"}, "digit", "5"},
		{"transport.ringing", "transport", nil, "state", "ringing"}, {"transport.answered", "transport", nil, "state", "answered"}, {"transport.failed", "transport", map[string]any{"error": map[string]any{"code": "bad"}}, "error_code", "bad"},
		{"session.usage.updated", "usage", map[string]any{"usage": map[string]any{"seconds": 2.5}, "context_window": map[string]any{"usage_ratio": 0.5}}, "seconds", 2.5},
		{"session.closed", "closed", map[string]any{"reason": "remote_hangup", "usage": map[string]any{"seconds": 4.0}}, "reason", "remote_hangup"},
		{"unknown", "other", nil, "wire_type", "unknown"},
	}
	for _, tc := range cases {
		t.Run(tc.wire+tc.kind, func(t *testing.T) {
			raw := map[string]any{"type": tc.wire, "event_id": "e"}
			for k, v := range tc.fields {
				raw[k] = v
			}
			e := parseEvent(raw)
			if e["type"] != tc.kind || e[tc.check] != tc.want || e["event_id"] != "e" {
				t.Fatal(e)
			}
			row := journalEvent(e, raw)
			if tc.kind == "usage" || tc.kind == "append_ack" {
				if row != nil {
					t.Fatal(row)
				}
				return
			}
			if row["event_id"] != "e" {
				t.Fatal(row)
			}
			if tc.kind == "transport" || tc.kind == "other" {
				if row["kind"] != "system" {
					t.Fatal(row)
				}
				b, _ := json.Marshal(row["payload"])
				r, _ := json.Marshal(raw)
				if string(b) != string(r) {
					t.Fatal("raw payload lost")
				}
			}
			if tc.kind == "error" {
				p := object(row["payload"])
				if p["type"] != "invalid" || p["client_event_id"] != "c" {
					t.Fatal(row)
				}
			}
		})
	}
	for _, r := range []string{"close_requested", "expired", "content", "remote_hangup", "connection_lost", "unknown", "new_reason"} {
		e := parseEvent(map[string]any{"type": "session.closed", "reason": r})
		want := r
		if r == "new_reason" {
			want = "unknown"
		}
		if e["reason"] != want || e["raw_reason"] != r {
			t.Fatal(e)
		}
	}
	for _, audio := range []string{"session.input_audio.append", "session.output_audio.delta"} {
		if parseEvent(map[string]any{"type": audio}) != nil {
			t.Fatal("audio reflected")
		}
	}
	e := parseEvent(map[string]any{"type": "session.input_transcript.delta", "start_ms": 5.9, "end_ms": true, "event_id": 42})
	if e["start_ms"] != int64(5) || e["end_ms"] != nil || e["event_id"] != nil {
		t.Fatal(e)
	}
}
func TestDedupeWindow(t *testing.T) {
	var d dedupe
	if !d.first("") || !d.first("") {
		t.Fatal("no id")
	}
	for i := 0; i < 4097; i++ {
		if !d.first(fmt.Sprint(i)) {
			t.Fatal(i)
		}
	}
	if !d.first("0") || d.first("4096") {
		t.Fatal("window")
	}
}
